const root=document.getElementById("cartRoot"),PROMOS={BLISS10:.1,TRADE15:.15};let promo=BLISS.store.get("bliss_promo",null);function render(){const e=BLISS.cart.items();if(!e.length){root.innerHTML=`<div class="empty-state" style="margin-bottom:60px">${icon("bag","lg")}<h2>Your cart is empty</h2><p>Discover pieces curated for beautiful living.</p>
        <div class="hero-cta" style="justify-content:center;margin-top:20px"><a class="btn" href="bathroom/bathtubs/freestanding-bathtubs/">Shop Bathtubs</a><a class="btn ghost" href="search.html?q=new">New Arrivals</a></div></div>`;return}const o=BLISS.cart.subtotal(),n=promo&&PROMOS[promo]?Math.round(o*PROMOS[promo]*100)/100:0;if(root.innerHTML=`<div class="cart-page">
      <div>
        <table class="cart-table">
          <thead><tr><th>Product</th><th class="unit">Price</th><th>Quantity</th><th>Total</th></tr></thead>
          <tbody>${e.map(t=>`<tr>
            <td><div class="prod"><a href="product.html"><img loading="lazy" decoding="async" src="img/${t.product.img}.webp"${imgSet(t.product.img,"96px")} alt=""></a><div>
              <span class="brand">${t.product.brand}</span><a class="name" href="product.html">${t.product.name}</a>
              ${t.variant?`<span class="variant">${esc(t.variant)}</span>`:""}
              ${t.product.weight==="freight"?"":`<span class="ship">${icon("check","sm")} Free standard shipping eligible</span>`}
            </div></div></td>
            <td class="unit">${priceOf(t.product)}</td>
            <td><div style="display:flex;gap:14px;align-items:center">${qtyControl(t)}<button class="line-remove" data-remove="${t.id}|${esc(t.variant)}" aria-label="Remove ${esc(t.product.name)}">${icon("trash","sm")}</button></div></td>
            <td><strong style="font-weight:500;color:var(--ink)">${priceOf(t.product,t.qty)}</strong></td>
          </tr>`).join("")}</tbody>
        </table>
        <div class="field" style="margin-top:28px;max-width:520px"><span>Order note <em>(optional)</em></span>
          <textarea id="note" rows="3" placeholder="Delivery instructions, project name, etc.">${esc(BLISS.store.get("bliss_note",""))}</textarea></div>
      </div>
      <aside class="summary">
        <h2>Order Summary</h2>
        ${(()=>{const t=e.reduce((a,s)=>a+(BLISS.onSale(s.product)?(s.product.was-s.product.cad)*s.qty:0),0);return t?`<div class="save-row">${icon("tag","sm")} You're saving ${price(t)} on sale items</div>`:""})()}
        <div class="sum-row"><span>Subtotal</span><span>${price(o)}</span></div>
        ${n?`<div class="sum-row" style="color:#4f7a48"><span>Discount (${promo})</span><span>\u2212${price(n)}</span></div>`:""}
        <div class="sum-row"><span>Shipping</span><span>${BLISS.cart.hasFreight()?"Calculated at checkout":"Free"}</span></div>
        <div class="sum-row"><span>Taxes</span><span class="muted">Calculated at checkout</span></div>
        <form class="promo" id="promoForm"><input id="promoIn" placeholder="Discount code" aria-label="Discount code" value="${promo||""}"><button class="btn ghost">Apply</button></form>
        <p class="promo-msg" id="promoMsg"></p>
        <div class="sum-row total"><span>Estimated total</span><strong><small data-currency-suffix>${BLISS.currency==="CAD"?"CAD":""}</small>${price(o-n)}</strong></div>
        <a class="btn block" href="checkout.html" style="margin-top:14px">${icon("lock","sm")} Proceed to Checkout</a>
        <div class="express-btns" style="margin-top:10px"><button class="xp-apple" type="button">Apple Pay</button><button class="xp-paypal" type="button">PayPal</button><button class="xp-gpay" type="button">G Pay</button></div>
        <div class="trust-mini">
          <div>${icon("shield","sm")} Secure checkout \xB7 SSL encrypted</div>
          <div>${icon("return","sm")} 14-day returns on eligible items</div>
          <div>${icon("phone","sm")} Questions? Call 1-855-366-1001</div>
        </div>
      </aside>
    </div>`,document.getElementById("note").addEventListener("input",t=>BLISS.store.set("bliss_note",t.target.value)),document.getElementById("promoForm").addEventListener("submit",t=>{t.preventDefault();const a=document.getElementById("promoIn").value.trim().toUpperCase();if(PROMOS[a])promo=a,BLISS.store.set("bliss_promo",a),render(),toast(`Code ${a} applied`);else{const s=document.getElementById("promoMsg");s.className="promo-msg bad",s.textContent=a?"That code isn't valid. Try BLISS10 for this demo.":"Enter a code."}}),promo&&PROMOS[promo]){const t=document.getElementById("promoMsg");t.className="promo-msg ok",t.textContent=`${Math.round(PROMOS[promo]*100)}% off applied.`}}document.addEventListener("cart:change",render),render();const inCart=new Set(BLISS.cart.items().map(e=>e.id));document.getElementById("alsoRail").innerHTML=["riobel-bath-faucet","riobel-momenti-shower","vc-pendant","toto-drake","kohler-workstation-sink","va-amalfi"].filter(e=>!inCart.has(e)).map(BLISS.byId).map(productCard).join("");
